"use client";

import { useMemo } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { createAvatar } from "@dicebear/core";
import { adventurer } from "@dicebear/collection";

/**
 * A friendly "little person" agent character.
 *
 * The face itself is generated by DiceBear (an external avatar-generation
 * engine) from a deterministic seed, so each agent always gets the same happy
 * face. framer-motion then gives the character a gentle, always-on idle
 * float + a hover "hop" so they feel alive and eager to help.
 */
export function AgentAvatar({
  seed,
  color,
  size = 120,
  /** Index lets each character bob slightly out of phase with the others. */
  index = 0,
  className = "",
}: {
  seed: string;
  color: string;
  size?: number;
  index?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  // Escape hatch: /alternative?still=1 freezes idle motion (handy for capture).
  const still =
    typeof window !== "undefined" &&
    window.location.search.includes("still");
  const noMotion = reduce || still;

  const svg = useMemo(() => {
    const accent = color.replace("#", "");
    return createAvatar(adventurer, {
      seed,
      size,
      radius: 50,
      backgroundColor: [accent],
      backgroundType: ["solid"],
      // friendly, smiley mouth + bright eyes (adventurer variant names)
      mouth: ["variant01", "variant07", "variant12", "variant16", "variant21"],
      eyes: ["variant01", "variant02", "variant07", "variant12", "variant26"],
    }).toString();
  }, [seed, color, size]);

  const float = noMotion
    ? {}
    : {
        animate: { y: [0, -8, 0] },
        transition: {
          duration: 3.2 + (index % 4) * 0.4,
          repeat: Infinity,
          ease: "easeInOut" as const,
          delay: (index % 5) * 0.25,
        },
      };

  return (
    <motion.div
      {...float}
      whileHover={noMotion ? undefined : { scale: 1.08, rotate: -3 }}
      className={className}
      style={{ width: size, height: size, willChange: "transform" }}
    >
      <div
        role="img"
        aria-label={`${seed.split("-")[0]} agent avatar`}
        className="h-full w-full drop-shadow-[0_12px_24px_rgba(17,24,39,0.18)]"
        style={{ borderRadius: "9999px" }}
        // DiceBear returns a trusted, self-generated SVG string.
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    </motion.div>
  );
}
